-- MT2009_PLUS_SKILL9_V1: the 9th skills of Yohara - skill_proto 176-182 (tools/yskill9/gen_yskill9_sql.py;
-- server-patches/skill9/README.md). Idempotent: the set is widened once, the rows are written whole every run.
-- Tarcza Eteru needs SKILL_FLAG_PARTY (bit 28): setFlag gets ATTACK_BLEEDING (27) and PARTY (28) when it has no PARTY;
-- any other shape of the set stops the script (the db core reads setFlag+0 - a member in another place moves the bits).
SET @yskill9_t := (SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'world' AND TABLE_NAME = 'skill_proto' AND COLUMN_NAME = 'setFlag');
SET @yskill9_sql := IF(@yskill9_t LIKE '%''PARTY''%', 'DO 0',
    IF(@yskill9_t LIKE '%,''THIRD_POINT_SELFONLY'')',
       CONCAT('ALTER TABLE world.skill_proto MODIFY setFlag ', LEFT(@yskill9_t, LENGTH(@yskill9_t) - 1), ',''ATTACK_BLEEDING'',''PARTY'') DEFAULT '''''),
       'SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''yskill9: world.skill_proto.setFlag has an unexpected shape'''));
PREPARE yskill9_stmt FROM @yskill9_sql;
EXECUTE yskill9_stmt;
DEALLOCATE PREPARE yskill9_stmt;

