-- the check: seven rows, Tarcza Eteru with PARTY
SELECT IF((SELECT COUNT(*) FROM world.skill_proto WHERE dwVnum BETWEEN 176 AND 182) = 7 AND (SELECT FIND_IN_SET('PARTY', setFlag) FROM world.skill_proto WHERE dwVnum = 182) > 0, 'yskill9 ok', NULL) INTO @yskill9_ok;
SET @yskill9_sql := IF(@yskill9_ok IS NULL, 'SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''yskill9: rows missing''', 'DO 0');
PREPARE yskill9_stmt FROM @yskill9_sql;
EXECUTE yskill9_stmt;
DEALLOCATE PREPARE yskill9_stmt;
